<summary>Proof script: live-proof-before.ts</summary>

```ts
// Demonstrates unbounded growth on the original (un-patched) code path.
import { resolveToolsBySender } from "./src/config/group-policy.ts";

const UNIQUE_KEYS = 5_000;
let warningsEmitted = 0;
const origEmit = process.emitWarning;
process.emitWarning = (...args) => {
  const [msg] = args;
  if (typeof msg === "string" && msg.includes("deprecated")) warningsEmitted++;
};

for (let i = 1; i <= UNIQUE_KEYS; i++) {
  resolveToolsBySender({
    toolsBySender: { [`legacy-key-${i}`]: { allow: ["read"] }, "*": { deny: ["exec"] } },
    senderId: `sender-${i}`,
  });
}
process.emitWarning = origEmit;

console.log(`→ ${warningsEmitted} deprecation warnings emitted.`);
console.log(`→ All ${UNIQUE_KEYS} entries permanently retained in the Set.`);
```
</details>

<details>
<summary>Proof script: live-proof.ts</summary>

```ts
// Verifies LRU cap, eviction, and touch-on-read on the patched module.
import { testing, resolveToolsBySender } from "./src/config/group-policy.ts";

const { cacheMeta, setWarnedLegacyToolsBySenderKeyTestOnly } = testing;
const CAP = cacheMeta.MAX_WARNED_LEGACY_TOOLS_BY_SENDER_KEYS;

// Seed cache to cap-1.
for (let i = 1; i <= CAP - 1; i++) {
  setWarnedLegacyToolsBySenderKeyTestOnly(`legacy-key-${i}`);
}

// Add one more via resolveToolsBySender — now at cap.
resolveToolsBySender({
  toolsBySender: { "legacy-key-0": { allow: ["read"] }, "*": { deny: ["exec"] } },
  senderId: "some-id",
});

// Push 5 extra entries past the cap.
for (let i = CAP; i < CAP + 5; i++) {
  setWarnedLegacyToolsBySenderKeyTestOnly(`legacy-key-${i}`);
}

// "legacy-key-1" was the first seeded entry → evicted → re-warns.
let reWarned = false;
process.emitWarning = (...args) => {
  const [msg] = args;
  if (typeof msg === "string" && msg.includes("legacy-key-1")) reWarned = true;
};
resolveToolsBySender({
  toolsBySender: { "legacy-key-1": { allow: ["read"] }, "*": { deny: ["exec"] } },
  senderId: "some-id",
});
console.log(`"legacy-key-1" ${reWarned ? "re-warned (evicted)" : "still cached"}.`);

// Touch "legacy-key-2" 42 times → LRU touch promotes it.
for (let i = 0; i < 42; i++) {
  resolveToolsBySender({
    toolsBySender: { "legacy-key-2": { allow: ["read"] }, "*": { deny: ["exec"] } },
    senderId: "irrelevant-id",
  });
}
// Push 500 more entries — "legacy-key-2" should survive.
for (let i = CAP + 5; i < CAP + 500; i++) {
  setWarnedLegacyToolsBySenderKeyTestOnly(`legacy-key-${i}`);
}
let reWarnedHot = false;
process.emitWarning = (...args) => {
  const [msg] = args;
  if (typeof msg === "string" && msg.includes("legacy-key-2")) reWarnedHot = true;
};
resolveToolsBySender({
  toolsBySender: { "legacy-key-2": { allow: ["read"] }, "*": { deny: ["exec"] } },
  senderId: "irrelevant-id",
});
console.log(`"legacy-key-2" ${reWarnedHot ? "evicted (BUG!)" : "survived (LRU touch working)"}.`);
```
</details>

